$_MODULE['<{sudemi}prestashop>sudemi_6a12dc9c382d5be5306dbf09295f608a'] = 'Les acheteurs paient dans cette devise, et les commandes que sudemi vous envoie sont dans cette devise. Votre versement de sudemi est en euros ; pour toute autre devise, la société de carte prélève des frais de conversion d\'environ 2 pour cent sur votre versement.';
$_MODULE['<{sudemi}prestashop>sudemi_1d75c6794f7c6f15f9d20716a7534e15'] = 'sudemi n\'accepte pas les paiements en %1$s, vos produits ne sont donc pas montrés aux acheteurs. sudemi accepte ces devises : %2$s. Choisissez-en une comme devise par défaut de cette boutique, puis envoyez à nouveau le catalogue.';
$_MODULE['<{sudemi}prestashop>sudemi_a0e397dee2f1c5834ab1d445aec6cdc6'] = 'Cette boutique vend maintenant en %1$s, mais sudemi a encore %2$s. Envoyez à nouveau le catalogue pour que les acheteurs voient les bons prix.';
